import {regionMaps as outdoorMaps,mapSource} from '../region-maps.js';
import {storyMaps} from '../story-maps.js';
import {storyWaypoints} from '../story-data.js';
export const regionMaps={...outdoorMaps,...storyMaps};
import {puzzles} from '../puzzle-data.js';
import {collectionItems,artifactCandidates} from '../collection-data.js';
import {artifactForCandidate,artifactDone} from './artifacts.js';
export {mapSource};
export const mapNodeMatches=(node,target)=>node.target===target||node.alsoTargets?.includes(target);
export function mapNodeDone(node,progress){const site=node.target?.startsWith('artifact-')?artifactForCandidate(node.target.slice(9)):null;return site?artifactDone(progress,site.id):[node.target,...node.alsoTargets||[]].every(target=>target&&progress.steps[target]?.status==='completed');}
export function mapNodeTitle(node){const puzzle=puzzles.find(p=>'puzzle-'+p.id===node.target),item=collectionItems.find(c=>'collectible-'+c.id===node.target),artifact=artifactCandidates.find(a=>'artifact-'+a.id===node.target),waypoint=storyWaypoints.find(w=>'waypoint-'+w.id===node.target);return puzzle?puzzle.label+' · '+puzzle.title:item?item.title:artifact?artifact.title:waypoint?waypoint.title:node.caption||node.description||node.label;}
export function mapSvg(region,{escape,progress,selected}){
 const map=regionMaps[region];if(!map)return '';
 const [nx,ny]=map.north||[0,0],end=[nx*45,ny*45],back=[nx*29,ny*29],wing=[-ny*9,nx*9];
 const compass=map.north?`<g class="map-compass" transform="translate(920 85)" aria-label="大致北向"><path d="M0 0L${end.join(' ')}M${back[0]+wing[0]} ${back[1]+wing[1]}L${end.join(' ')}L${back[0]-wing[0]} ${back[1]-wing[1]}"/><text x="${nx*67}" y="${ny*67+10}" text-anchor="middle">N</text></g>`:'';
 return `<svg class="region-map-svg" viewBox="0 0 1000 650" role="group" aria-label="${escape(map.name||region)} 位置示意圖" xmlns="http://www.w3.org/2000/svg"><title>${escape(map.name||region)} 位置示意圖</title>${compass}<g class="map-paths" fill="none">${map.paths.map(path=>'<polyline points="'+path.map(xy=>xy.join(',')).join(' ')+'"/>').join('')}</g>${map.nodes.map(node=>`<a href="#${escape(node.target||'map-'+node.id)}" data-map-node="${escape(node.id)}" ${node.target?'data-map-target="'+escape(node.target)+'"':''} class="map-node map-${node.kind}${mapNodeDone(node,progress)?' map-done':''}${selected===node.id?' map-selected':''}" aria-label="${escape(node.label+' · '+mapNodeTitle(node)+(mapNodeDone(node,progress)?' · 已取得':''))}"><title>${escape(mapNodeTitle(node)+(mapNodeDone(node,progress)?' · 已取得':'')+(node.description?' · '+node.description:''))}</title><circle cx="${node.x}" cy="${node.y}" r="25"/><text x="${node.x}" y="${node.y+1}" text-anchor="middle" dominant-baseline="central">${escape(node.label)}</text>${node.caption?`<text class="map-caption" x="${node.x}" y="${node.y+(node.captionDy||52)}" text-anchor="middle">${escape(node.caption)}</text>`:''}${mapNodeDone(node,progress)?`<path class="map-completed-mark" d="M${node.x+13} ${node.y-24}l6 6 12-14"/>`:''}</a>`).join('')}</svg>`;
}
export function regionMapHtml(region,options,{dialog=false}={}){
 const map=regionMaps[region];if(!map)return '';
 const node=map.nodes.find(n=>n.id===options.selected);
 return `<section class="region-map-panel" data-map-region="${region}" aria-label="${region} 區域地圖"><div class="map-heading"><h2>${options.escape(map.name||region+' 區域示意圖')}</h2>${dialog?'<label class="map-fit-label"><input type="checkbox" data-map-fit checked>全圖</label>':'<button type="button" data-open-map>放大地圖</button>'}</div>${options.mapKeys?.length>1?`<label class="map-layer-label">範圍<select data-map-layer>${options.mapKeys.map(key=>`<option value="${options.escape(key)}" ${region===key?'selected':''}>${options.escape(regionMaps[key].name||key)}</option>`).join('')}</select></label>`:''}<div class="map-canvas map-fit">${mapSvg(region,options)}</div><p class="map-selection" data-map-selection>${node?options.escape(mapNodeTitle(node)):'點圖上標記，或在下方選擇位置。'}</p><label class="map-select-label">定位<select data-map-select><option value="">選擇謎題或收集品…</option>${map.nodes.map(n=>'<option value="'+options.escape(n.id)+'" '+(n.id===options.selected?'selected':'')+'>'+options.escape(n.label+' · '+mapNodeTitle(n))+'</option>').join('')}</select></label><p class="map-legend">${map.legend?options.escape(map.legend).replaceAll('\n','<br>'):'1–8 正規 · L1／L2 遺失 · G 黃金<br>實 實驗室 · T／L 錄音 · M 光影<br>★ 雕像 · A 遺物候選 · 火 Spark · 文 終端<br>綠色＋勾號：已取得（遺物跨區連動）'}</p><p class="map-orientation">${options.escape(map.orientation)}</p>${map.pending?'<p class="map-pending">待查證：'+options.escape(map.pending)+'</p>':''}${dialog?'<p class="map-note">'+options.escape(map.note)+'</p><a href="'+(map.sourceUrl||mapSource.url)+'" target="_blank" rel="noopener noreferrer">地標查證來源 ↗</a>':''}</section>`; // taste-skill-ignore: ★ 是本遊戲星星收集的既有識別，非裝飾 emoji。
}
export const mapLocateButton=(target,escape)=>`<button type="button" class="map-locate" data-map-locate="${escape(target)}" aria-label="在區域地圖定位">定位</button>`;
